import * as OneSignal from '@onesignal/node-onesignal';

const configuration = OneSignal.createConfiguration({
  restApiKey: process.env.ONESIGNAL_API_KEY!,
});
const client = new OneSignal.DefaultApi(configuration);

const notification = new OneSignal.Notification();
notification.app_id = process.env.ONESIGNAL_APP_ID!;
notification.contents = { en: 'Your order has shipped! Track it now.' };
notification.headings = { en: 'Order Update' };

// Send to specific users by external ID
notification.include_aliases = {
  external_id: ['user-123', 'user-456'],
};
notification.target_channel = 'push';

const response = await client.createNotification(notification);
console.log('Notification ID:', response.id);
console.log('Recipients:', response.recipients);
